+		return fmt.Errorf("job worker service requires root privileges to configure cgroups")
+	}
+	if err := checkKernelVersion(); err != nil {
+		return err
+	}
+	if err := checkCgroupMount(); err != nil {
+		return err
+	}
+	if err := configureControllers(); err != nil {
+		return err
+	}
+	return nil
+}
+
+func checkKernelVersion() error {
+	var u unix.Utsname
+	if err := uname(&u); err != nil {
+		return fmt.Errorf("failed to get kernel info: %w", err)
+	}
+
+	// Parse release string (e.g., "5.15.0-100-generic")
+	// unix.Utsname Release is a byte array
+	end := bytes.IndexByte(u.Release[:], 0)
+	if end == -1 {
+		end = len(u.Release)
+	}
+	release := string(u.Release[:end])
+	var major, minor int
+	if _, err := fmt.Sscanf(release, "%d.%d", &major, &minor); err != nil {
+		return fmt.Errorf("failed to parse kernel version %q: %w", release, err)
+	}
+
+	if major < 5 || (major == 5 && minor < 14) {
+		return fmt.Errorf("kernel version %s is too old; 5.14+ required", release)
+	}

