+	CAPath string
+	// CertPath is the path to the client's certificate file for mTLS.
+	CertPath string
+	// KeyPath is the path to the client's private key file for mTLS.
+	KeyPath string
+	// OutputJSON indicates whether the output should be formatted as JSON.
+	OutputJSON bool
